        block: "    //#region mpd-delta rtl-ip-carrier (mpd LOCAL ADAPTATION; re-applied by scripts/patch-agent-teams-fixes.mjs)\n    // Carrier hook (silicon docs/sync-policy.md §1; contract source: silicon presets/README.md\n    // §\"The t15 hook contract\"): merge the silicon bundle's `rtl-ip` agent-teams profile into this\n    // row's profile set. It MUST run first in apply() so every consumer below — resolved.profiles,\n    // the captain prompt, the slash command and the gesture boundary — sees ONE merged set.\n    // Read at apply time, never at import time. Resolution is PRIORITY-ORDERED and the FIRST\n    // candidate that READS successfully DECIDES (t8 / R5.3 ruling V-hook-corrupt-fallthrough):\n    //   - absent / unreadable (ENOENT)          -> continue; an mpd-only install is the normal case\n    //   - readable, parses to an object         -> return it\n    //   - readable, corrupt or non-object       -> ONE warning naming the path and the reason, then {}\n    //                                              and STOP; it never continues to a farther candidate,\n    //                                              because a nearer copy is the more authoritative one\n    //                                              and substituting a silently downgraded profile is\n    //                                              the exact unreported-downgrade class this audit removes\n    // All candidates absent -> {} with no warning. The boot never throws on any of these paths.\n    // PRESENCE is the discriminator, not parseability: a nearer copy that exists means the farther\n    // copies are stale, so substituting one silently is a downgrade and the operator gets no signal.\n    // ENOENT continues because an absent silicon bundle is the documented normal state (mpd-only\n    // install); any OTHER read failure (EACCES/EISDIR/...) means the path EXISTS but cannot be read —\n    // a broken installation — and that stops with a warning instead of being skipped.\n    // mpd's own profiles win every key collision, and no member shape is pre-validated here —\n    // resolveTeamProfile already rejects unknown names, empty/duplicate keys and >16 profiles at\n    // create time.\n    const loadSiliconProfiles = () => {\n        const fs = process.getBuiltinModule(\"node:fs\");\n        const path = process.getBuiltinModule(\"node:path\");\n        const require = process.getBuiltinModule(\"node:module\").createRequire(import.meta.url);\n        const candidates = [];\n        try {\n            candidates.push(require.resolve(\"@mpd-dsh/silicon/presets/rtl-ip.profile.json\"));\n        }\n        catch { /* package not resolvable: the bundle-relative walk-up below may still find it */ }\n        let dir = path.dirname(process.getBuiltinModule(\"node:url\").fileURLToPath(import.meta.url));\n        for (let up = 0; up < 8; up += 1) {\n            candidates.push(path.join(dir, \"node_modules\", \"@mpd-dsh\", \"silicon\", \"presets\", \"rtl-ip.profile.json\"));\n            const parent = path.dirname(dir);\n            if (parent === dir)\n                break;\n            dir = parent;\n        }\n        // Presence decides, not parseability: the FIRST candidate that EXISTS ends the search, so a\n        // nearer copy is never silently superseded by a farther (older/different) one.\n        //   - absent (ENOENT)          -> keep looking; an mpd-only install is the normal case\n        //   - exists but unreadable    -> warn once naming the path + error, then {} (broken install)\n        //   - readable but corrupt /\n        //     non-object (incl. null,\n        //     arrays)                  -> warn once naming the path, then {}\n        //   - readable valid object    -> merge it\n        for (const file of candidates) {\n            let text;\n            try {\n                text = fs.readFileSync(file, \"utf8\");\n            }\n            catch (err) {\n                if (err?.code === \"ENOENT\")\n                    continue;\n                console.warn(`[mpd] agent-teams: cannot read the silicon rtl-ip profile at ${file} (${err?.code ?? err}); ignoring it`);\n                return {};\n            }\n            let parsed;\n            try {\n                parsed = JSON.parse(text);\n            }\n            catch {\n                console.warn(`[mpd] agent-teams: ignoring the silicon rtl-ip profile at ${file} (invalid JSON)`);\n                return {};\n            }\n            if (parsed !== null && typeof parsed === \"object\" && !Array.isArray(parsed))\n                return parsed;\n            console.warn(`[mpd] agent-teams: ignoring the silicon rtl-ip profile at ${file} (not a JSON object)`);\n            return {};\n        }\n        return {};\n    };\n    config = { ...config, profiles: { ...loadSiliconProfiles(), ...(config.profiles ?? {}) } };\n    //#endregion mpd-delta rtl-ip-carrier",
